// Importing necessary modules and components
import React, { useState, useEffect, useCallback, useRef } from 'react'; // Import useCallback and useRef hooks
import axios from 'axios';
import { Link } from 'react-router-dom';
import Modal from 'react-modal'; // Import the Modal component from the react-modal library
import Slider from 'react-slick'; // Import the Slider component from the react-slick library
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import YouTube from 'react-youtube'; // Import the YouTube component from the react-youtube library
import Loader from 'react-loader-spinner'; // Import the Loader component from the react-loader-spinner library
import '../CSS/movieslist.css';
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';
function MoviesList({ category, addToWatchlist }) {
  // Setting up state for the list of movies, selected movie, and trailer video
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [trailerVideo, setTrailerVideo] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  // Create a ref for the subtitle element
  const subtitle = useRef(null);

  // Use useCallback hook to memoize playTrailer function
  const playTrailer = useCallback(async (movie) => {
    setIsLoading(true);
    setSelectedMovie(movie);
    const response = await axios.get(
      `${baseUrl}/movie/${movie.id}/videos`,
      {
        params: {
          api_key: apiKey,
        },
      }
    );
    const trailer = response.data.results.find(
      (video) => video.type === 'Trailer' && video.site === 'YouTube'
    );
    setTrailerVideo(trailer);
    setIsLoading(false);
  }, [apiKey, baseUrl]); // Pass dependencies

  // Use useCallback hook to memoize closeTrailer function
  const closeTrailer = useCallback(() => {
    setSelectedMovie(null);
    setTrailerVideo(null);
  }, []); // No dependencies

  useEffect(() => {
    // Use async/await syntax inside useEffect hook
    const fetchData = async () => {
      try {
        let endpoint;
        switch (category) {
          case 'hollywood':
            endpoint = '/movie/popular';
            break;
          case 'bollywood':
            endpoint = '/discover/movie?with_original_language=hi';
            break;
          case 'lollywood':
            endpoint = '/discover/movie?with_original_language=ur';
            break;
          default:
            return;
        }
        const response = await axios.get(`${baseUrl}${endpoint}`, {
          params: {
            api_key: apiKey,
          },
        });
        setMovies(response.data.results);
      } catch (error) {
        // Handle errors
        console.error(error);
      }
    };
    fetchData();
  }, [category, apiKey, baseUrl]); // Pass dependencies

  // Create settings object for Slider component
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 4,
    slidesToScroll: 4,
    lazyLoad: true, // Add lazyLoad prop
  };

  return (
    <div>
      <h2>{category}</h2>
      <div className="movies-list">
        {/* Use Slider component instead of scroll buttons */}
        <Slider {...settings}>
          {movies.map((movie) => (
            <div key={movie.id} className="movie-card">
              <Link to={`/movie/${movie.id}`}>
                <img
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                  alt={movie.title}
                  style={{ height: '300px' }}
                  onLoad={handleImageLoad} // Add an event handler
                />
                <h3 style={{ height: '40px', zIndex: 1 }}>{movie.title}</h3>
              </Link>
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                <button onClick={() => addToWatchlist(movie)}>
                  Watchlist <span>+</span>
                </button>
                <button onClick={() => playTrailer(movie)}>
                  <span>▶</span> Play
                </button>
              </div>
            </div>
          ))}
        </Slider>
      </div>
      {trailerVideo && (
        <>
          <Modal
            isOpen={true}
            onRequestClose={closeTrailer}
            style={{
              overlay: {
                backgroundColor: 'rgba(0, 0, 0, 0.75)',
              },
              content: {
                top: '50%',
                left: '50%',
                right: 'auto',
                bottom: 'auto',
                marginRight: '-50%',
                transform: 'translate(-50%, -50%)',
                width: '80%',
                height: '80%',
                padding: 0,
                overflow : 'hidden',
              },
            }}
          >
            <div
              className={`modal-content ${trailerVideo ? 'open' : ''}`}
              style={{ position: 'relative', width: '100%', height: '100%' }} 
            >
              {isLoading && (
                <div>
                  <div className="loader">
                  {/* Use Loader component instead of div element */}
                  <Loader
                    type="TailSpin"
                    color="#00BFFF"
                    height={80}
                    width={80}
                  />
                </div>
                </div>
              )}
              {/* Use YouTube component instead of iframe element */}
              <YouTube
                videoId={trailerVideo.key}
                opts={{
                  height: '100%',
                  width: '100%',
                  playerVars: {
                    autoplay: 1,
                    },
                }}
              />

            </div>
          </Modal>         
          <button
            onClick={closeTrailer}
            onMouseEnter={(e) => (e.target.style.backgroundColor = '#000')}
            onMouseLeave={(e) => (e.target.style.backgroundColor = 'grey')}
            style={{
              position: 'fixed',
              top: 10,
              right: 10,
              fontSize: '24px',
              backgroundColor: 'grey',
              border: 'none',
              color: '#fff',
            }}
          >
            ×
          </button>
        </>
      )}
    </div>
  );
}
export default MoviesList;

